1	#!/usr/bin/env bun
2	/**
3	 * manage_turn_labels.ts — move a node's turn labels to the phase the run reached.
4	 *
5	 * Two labels say whose ball the node's turn is, and they are complements:
6	 *
7	 *   - `running` — a run took the turn: `atomaton/in-progress` on,
8	 *     `atomaton/waiting-for-person` off.
9	 *   - `with-person` — the turn came back to a person: `in-progress` off,
10	 *     `waiting-for-person` on.
11	 *   - `closed` — the node closed (#352): both come off, neither goes on. The state
12	 *     read the other two phases make gates this one too: a node the read says is
13	 *     open gets no write at all — the runner's end-of-run strip fires on every
14	 *     ending, open nodes included, and must not strip the labels a live turn is
15	 *     wearing — while a node the read says is closed (or one the read could not
16	 *     answer) is stripped of what it wears.
17	 *
18	 * One script, because the labels are moved at the same moments by the same
19	 * callers (the runner's start and release steps, a refused hand-off, a stop that
20	 * ends a park, the strips that follow a close) and a caller that moved one without
21	 * the other would leave a node wearing both or neither. The names come from
22	 * `chain.labels` in config.yaml, with defaults in `adapters/runner/config.ts`; see
23	 * `lib/turn-labels.ts` for the rule.
24	 *
25	 * Best-effort: never fails the calling step, only logs a warning (matching the
26	 * previous `2>/dev/null || true` bash behavior).
27	 *
28	 * Usage:
29	 *   manage_turn_labels.ts --phase running|with-person|closed --number N [--repo OWNER/REPO]
30	 */
31	import { parseArgs } from "node:util";
32	import { applyTurnLabels } from "./lib/turn-labels.ts";
33	import { defineScript } from "./lib/script-ref.ts";
34	
35	export interface ManageTurnLabelsArgs {
36	  phase: "running" | "with-person" | "closed";
37	  number: string | number;
38	  repo?: string;
39	}
40	
41	export const ref = defineScript<ManageTurnLabelsArgs>(import.meta.url);
42	
43	const PHASES = ["running", "with-person", "closed"] as const;
44	
45	function main(): void {
46	  const { values } = parseArgs({
47	    args: Bun.argv.slice(2),
48	    options: {
49	      phase: { type: "string" },
50	      number: { type: "string" },
51	      repo: { type: "string" },
52	    },
53	  });
54	
55	  if (!PHASES.includes(values.phase as (typeof PHASES)[number])) {
56	    console.error(`usage: manage_turn_labels.ts --phase ${PHASES.join("|")} --number N [--repo OWNER/REPO]`);
57	    process.exit(2);
58	  }
59	  if (!values.number) {
60	    console.error(`usage: manage_turn_labels.ts --phase ${PHASES.join("|")} --number N [--repo OWNER/REPO]`);
61	    process.exit(2);
62	  }
63	
64	  applyTurnLabels(values.phase as (typeof PHASES)[number], values.repo ?? "", String(values.number));
65	}
66	
67	if (import.meta.main) main();

